using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("AsyncAwait")]
    [TestClass]
    public class RJIT_CR_AA_R_00002: MsTestBase   
    {
        /*
         * Code Rule RJIT_CR_AA_00002 ensures that asynchronous methods in C# which only return a task from an await call should instead directly return the task without using await.
         */
         [TestMethod]
         public void Async_Methods_Which_Returns_Only_Await_Task_Should_Just_Return_The_Async_Call()
         {
             var returnAwaitOnly = (from @records in Records
            from @method in @records.Methods
            where method.Statements.Count < 2 && method.MethodBody.Contains("await") && method.MethodBody.DoesNotContain("= await") && method.LineStatements.Count < 2
        select new
        {
            Error = $@"
Do not use await if you only return a task
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Record:  {@records.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method: {method.MethodValue}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: {method.MethodValue.Replace("return await", "return").Replace(".ConfigureAwait(false)", string.Empty).Replace(".ConfigureAwait(true)", string.Empty)}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
        }).ToImmutableList();
             Assert.IsTrue(returnAwaitOnly.IsEmpty(),
        @$"
Documentation: {DocumentationDomain}#RJIT_CR_AA_00002

Invalid response type. Findings: '{returnAwaitOnly.Count}': {Environment.NewLine}{returnAwaitOnly.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
         }
    }
}
